questionvariables.text:
/* Context bank: rows = entities, columns = categories, the two matrices = two
   time periods, so M+T is the combined total and T-M is the change. Each list
   holds 3 items so the question works at either 2 or 3 rows / 2 or 3 columns. */
allcats : [ ["Fiction","Science","History"],
            ["tomatoes","onions","potatoes"],
            ["bread","milk","sugar"],
            ["maize","beans","sorghum"],
            ["elephants","zebras","giraffes"],
            ["immunisations","antenatal visits","dental visits"] ];
allents : [ ["Class 1","Class 2","Class 3"],
            ["Stall A","Stall B","Stall C"],
            ["the Eastleigh branch","the Westlands branch","the Kasarani branch"],
            ["Farm A","Farm B","Farm C"],
            ["Tsavo","Amboseli","Nairobi"],
            ["the Embu clinic","the Meru clinic","the Nyeri clinic"] ];
allper  : [ ["Monday","Tuesday"],
            ["Saturday","Sunday"],
            ["Week 1","Week 2"],
            ["last season","this season"],
            ["the 2024 count","the 2025 count"],
            ["January","February"] ];
allunit : ["books","kilograms","items","bags","animals","patients"];

/* string helpers */
numword(k) := if is(k=2) then "two" else "three";
capword(k) := if is(k=2) then "Two" else "Three";
listjoin(L) := if is(length(L)=1) then L[1]
  else sconcat(simplode(rest(L,-1), ", "), " and ", last(L));

/* choose the variant */
ctx  : rand(6)+1;
nrow : rand(2)+2;          /* 2 or 3 entities  */
ncol : rand(2)+2;          /* 2 or 3 categories */

cats : allcats[ctx];  catsU : makelist(cats[j], j, 1, ncol);
ents : allents[ctx];  entsU : makelist(ents[i], i, 1, nrow);
per  : allper[ctx];   per1 : per[1];  per2 : per[2];
unit : allunit[ctx];
catStr : listjoin(catsU);
entStr : listjoin(entsU);
nE    : capword(nrow);     /* "Two"/"Three" to start a sentence */
nElow : numword(nrow);     /* "two"/"three" mid-sentence        */
nC    : numword(ncol);     /* "two"/"three" categories          */

/* Design backwards: pick M (3..14) and a non-zero change D in {-3..4}\{0},
   then T = M + D so every entry of T is >= 0 and D is never the zero matrix. */
MM : genmatrix(lambda([i,j], rand(12)+3), nrow, ncol);
DD : genmatrix(lambda([i,j], rand([-3,-2,-1,1,2,3,4])), nrow, ncol);
TT : MM + DD;

sumM    : MM + TT;         /* (a) total            */
diffM   : TT - MM;         /* (b) change ( = D )   */
diffRev : MM - TT;         /* error: subtracted in the wrong order */
onesM   : genmatrix(lambda([i,j], 1), nrow, ncol);
wrongSum  : sumM + onesM;  /* generic wrong answers for the catch-all branches */
wrongDiff : diffM + onesM;
